module SubstringCounter(\n    input clk,\n    input rst_n,\n    input start,\n    input [5:0] e,\n    input [3:0] n_digits [0:18],\n    output reg [63:0] count,\n    output reg done\n);\n    // State declarations\n    localparam [3:0] IDLE           = 4'd0;\n    localparam [3:0] LOOKUP         = 4'd1;\n    localparam [3:0] BUILD_KMP      = 4'd2;\n    localparam [3:0] INIT_DP        = 4'd3;\n    localparam [3:0] PREPARE_LOOP   = 4'd4;\n    localparam [3:0] ITERATE_DIGITS = 4'd5;\n    localparam [3:0] ITERATE_STATES = 4'd6;\n    localparam [3:0] ITERATE_DIGITS_VALS = 4'd7;\n    localparam [3:0] SUM            = 4'd8;\n    localparam [3:0] DONE_STATE     = 4'd9;\n    reg [3:0] state, next_state;\n    \n    // Pattern ROM signals\n    reg [3:0] pattern [0:18];\n    reg [5:0] m;\n    \n    // KMP transition table\n    reg [4:0] transition [0:19][0:9];\n    reg [4:0] failure [0:18];\n    \n    // DP tables\n    reg [63:0] current_dp [0:1][0:1][0:19];  // tight x started x state (0-m)\n    reg [63:0] next_dp [0:1][0:1][0:19];\n    \n    // Loop counters\n    reg [5:0] i;  // For position\n    reg [4:0] s;  // For automaton state\n    reg [3:0] d;  // For digit value\n    reg [1:0] tight;\n    reg [1:0] started;\n    \n    // Temporary variables\n    reg new_tight;\n    reg new_started;\n    reg [4:0] new_state;\n    \n    // Cycle counter to prevent infinite loops\n    reg [7:0] cycle_count;\n    \n    // State machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            count <= 64'd0;\n            cycle_count <= 8'd0;\n            \n            // Clear pattern ROM\n            for (i = 0; i < 19; i = i + 1) begin\n                pattern[i] <= 4'd0;\n            end\n            \n            // Clear DP tables\n            for (tight = 0; tight <= 1; tight = tight + 1) begin\n                for (started = 0; started <= 1; started = started + 1) begin\n                    for (s = 0; s <= 19; s = s + 1) begin\n                        current_dp[tight][started][s] <= 64'd0;\n                        next_dp[tight][started][s] <= 64'd0;\n                    end\n                end\n            end\n            \n            // Clear KMP tables\n            for (i = 0; i <= 18; i = i + 1) begin\n                failure[i] <= 5'd0;\n            end\n            for (s = 0; s <= 19; s = s + 1) begin\n                for (d = 0; d <= 9; d = d + 1) begin\n                    transition[s][d] <= 5'd0;\n                end\n            end\n        end else begin\n            state <= next_state;\n            cycle_count <= cycle_count + 8'd1;\n            \n            // Done pulse only lasts one cycle\n            if (state == DONE_STATE) begin\n                done <= 1'b1;\n            end else begin\n                done <= 1'b0;\n            end\n            \n            // Default transition to prevent hangs\n            if (cycle_count > 8'd200) begin\n                next_state <= IDLE;\n            end\n            \n            case (state)\n                IDLE: begin\n                    count <= 64'd0;\n                    if (start) begin\n                        next_state <= LOOKUP;\n                    end\n                end\n                \n                LOOKUP: begin\n                    // Simple ROM example - must extend for all e values\n                    case (e)\n                        6'd0: begin m <= 6'd1; pattern[0] <= 4'd1; end\n                        6'd1: begin m <= 6'd1; pattern[0] <= 4'd2; end\n                        6'd2: begin m <= 6'd1; pattern[0] <= 4'd4; end\n                        // ... Add all e values up to 63\n                        default: begin m <= 6'd0; end\n                    endcase\n                    next_state <= BUILD_KMP;\n                end\n                \n                BUILD_KMP: begin\n                    // Compute failure function (partial example)\n                    if (m > 6'd0) failure[0] <= 5'd0;\n                    // ... Actual KMP failure computation needed here\n                    next_state <= INIT_DP;\n                end\n                \n                INIT_DP: begin\n                    current_dp[1][0][0] <= 64'd1;  // Initial tight state, not started\n                    next_state <= PREPARE_LOOP;\n                end\n                \n                PREPARE_LOOP: begin\n                    i <= 6'd0;\n                    next_state <= ITERATE_DIGITS;\n                end\n                \n                ITERATE_DIGITS: begin\n                    if (i < 6'd19) begin\n                        // Reset next_dp for all states\n                        for (tight = 0; tight <= 1; tight = tight + 1) begin\n                            for (started = 0; started <= 1; started = started + 1) begin\n                                for (s = 0; s <= 19; s = s + 1) begin\n                                    next_dp[tight][started][s] <= 64'd0;\n                                end\n                            end\n                        end\n                        next_state <= ITERATE_STATES;\n                    end else begin\n                        next_state <= SUM;\n                    end\n                end\n                \n                ITERATE_STATES: begin\n                    tight <= 0;\n                    started <= 0;\n                    s <= 0;\n                    next_state <= ITERATE_DIGITS_VALS;\n                end\n                \n                ITERATE_DIGITS_VALS: begin\n                    if (tight <= 1) begin\n                        if (started <= 1) begin\n                            if (s <= m) begin\n                                d <= 4'd0;\n                                next_state <= DIGIT_LOOP;\n                            end else begin\n                                s <= s + 1;\n                            end\n                        end else begin\n                            started <= started + 1;\n                            s <= 0;\n                        end\n                    end else begin\n                        // Move to next position\n                        i <= i + 1;\n                        // Copy next_dp to current_dp\n                        for (tight = 0; tight <= 1; tight = tight + 1) begin\n                            for (started = 0; started <= 1; started = started + 1) begin\n                                for (s = 0; s <= 19; s = s + 1) begin\n                                    current_dp[tight][started][s] <= next_dp[tight][started][s];\n                                end\n                            end\n                        end\n                        next_state <= ITERATE_DIGITS;\n                    end\n                end\n                \n                DIGIT_LOOP: begin\n                    // Check digit constraints\n                    if (tight[0] && (d > n_digits[i])) begin\n                        // Digit exceeds current tight bound - skip\n                        if (d < 4'd9) d <= d + 1;\n                        else s <= s + 1;\n                    end else begin\n                        // Compute new states\n                        new_tight = tight[0] && (d == n_digits[i]);\n                        new_started = started[0] || (d != 4'd0);\n                        \n                        if (!new_started) begin\n                            new_state = 5'd0;\n                        end else begin\n                            new_state = transition[s][d];\n                        end\n                        \n                        // Update next_dp\n                        next_dp[new_tight][new_started][new_state] <=\n                            next_dp[new_tight][new_started][new_state] + current_dp[tight][started][s];\n                        \n                        if (d < 4'd9) d <= d + 1;\n                        else s <= s + 1;\n                    end\n                end\n                \n                SUM: begin\n                    // Sum all states where automaton reached m\n                    count <= current_dp[0][0][m] + current_dp[0][1][m] + current_dp[1][0][m] + current_dp[1][1][m];\n                    next_state <= DONE_STATE;\n                end\n                \n                DONE_STATE: begin\n                    next_state <= IDLE;\n                end\n                \n                default: next_state <= IDLE;\n            endcase\n        end\n    end\nendmodule